def seed_catalog_100(conn, now_iso: str = None) -> int:
    """
    Inserts 20 demo owners and ensures all 100 properties are seeded into DB.
    Idempotent by slug. Returns number of newly seeded properties.
    """
    if not now_iso:
        now_iso = datetime.now(timezone.utc).isoformat()
    cursor = conn.cursor()

    # 1. Ensure all 20 demo owners exist
    owner_id_map = {}
    for idx, (full_name, phone) in enumerate(DEMO_OWNERS):
        cursor.execute("SELECT id FROM users WHERE phone_number = ?", (phone,))
        row = cursor.fetchone()
        if row:
            owner_id_map[idx] = row["id"]
        else:
            new_uid = str(uuid.uuid4())
            cursor.execute("""
                INSERT INTO users (id, phone_number, full_name, telegram_id, role, is_active, created_at, updated_at)
                VALUES (?, ?, ?, ?, 'OWNER', 1, ?, ?)
            """, (new_uid, phone, full_name, 50000 + idx, now_iso, now_iso))
            owner_id_map[idx] = new_uid

    # 2. Seed 93 properties
    inserted_count = 0
    for p in NEW_93_PROPERTIES:
        slug = p["slug"]
        cursor.execute("SELECT id FROM properties WHERE slug = ?", (slug,))
        row = cursor.fetchone()
        if row:
            continue

        prop_id = str(uuid.uuid4())
        owner_id = owner_id_map.get(p["owner_idx"], list(owner_id_map.values())[0])

        cursor.execute("""
            INSERT INTO properties (
                id, owner_id, title, slug, description, property_type, region, micro_district,
                address_text, latitude, longitude, location_precision, road_condition,
                has_generator, water_source, heating_type, mobile_coverage,
                verification_status, is_published, photos_json, amenities_json, created_at, updated_at
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        """, (
            prop_id, owner_id, p["title"], p["slug"], p["description"], p["property_type"],
            p["region"], p["micro_district"], p["address_text"], p["latitude"], p["longitude"],
            p["location_precision"], p["road_condition"], p["has_generator"], p["water_source"],
            p["heating_type"], p["mobile_coverage"], p["verification_status"], p["is_published"],
            json.dumps(p["photos"]), json.dumps(p["amenities"]), now_iso, now_iso
        ))

        unit_id = str(uuid.uuid4())
        cursor.execute("""
            INSERT INTO rental_units (
                id, property_id, name, unit_category, standard_capacity, max_capacity,
                base_price_weekday, base_price_weekend, is_active, created_at
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, 1, ?)
        """, (
            unit_id, prop_id, p["unit_name"], p["unit_category"],
            p["standard_capacity"], p["max_capacity"],
            p["base_price_weekday"], p["base_price_weekend"], now_iso
        ))

        # Add slots for tapchan
        if p["property_type"] == "CHOYXONA_TAPCHAN":
            slots_data = [
                (str(uuid.uuid4()), unit_id, "Kunduzgi Sokin Hordiq", "09:00:00", "15:00:00", p["base_price_weekday"] * 0.6, p["base_price_weekend"] * 0.6),
                (str(uuid.uuid4()), unit_id, "Kechki Salqin Soatlar", "16:00:00", "23:00:00", p["base_price_weekday"] * 0.6, p["base_price_weekend"] * 0.6),
                (str(uuid.uuid4()), unit_id, "To'liq Kunlik VIP Tapchan", "09:00:00", "23:00:00", p["base_price_weekday"], p["base_price_weekend"])
            ]
            for s in slots_data:
                cursor.execute("""
                    INSERT INTO day_use_slots (
                        id, rental_unit_id, slot_name, start_time, end_time, price_weekday, price_weekend
                    ) VALUES (?, ?, ?, ?, ?, ?, ?)
                """, s)

        inserted_count += 1

    conn.commit()
    return inserted_count
